import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"Blodprøver","description":"","frontmatter":{},"headers":[],"relativePath":"blodprøver.md","filePath":"blodprøver.md"}`),a={name:`blodprøver.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="blodprøver" tabindex="-1">Blodprøver <a class="header-anchor" href="#blodprøver" aria-label="Permalink to “Blodprøver”">​</a></h1><p>Hvis du vil have hormonbehandling er blodprøver altid meget vigtige. Vi tager som regel blodprøver før vi starter hormonbehandling, og så igen 3 måneder efter vi er startet. Derefter holder vi også øje med vores niveauer hver 6.-12. måned, eller hver gang der er ændringer i vores dosering.</p><p>Som regel før man starter hormonbehandling, skal man have taget de følgende blodprøver:</p><ul><li>Komplet blodtælling (hvide blodlegemer, røde blodlegemer, hæmoglobin, blodplader, hæmatokrit, gennemsnitligt korpuskulært volumen)</li><li>Leverfunktionstests (ALT, AST, ALP, bilirubin)</li><li>Fastende blodsukker</li><li>Urea og elektrolytter / nyrepanel (kreatinin, eGFR, urea, kalium, natrium)</li><li>Lipid-/kolesterolpanel (total kolesterol, triglycerider, HDL, LDL)</li><li>Prolaktin (PRL)</li><li>Testosteron og østradiol (Total testosteron og E2)</li></ul><p>Hvis du er i gang med feminserende hormonbehandling og tager dine opfølgende blodprøver, skal du som regel have taget disse blodprøver:</p><ul><li>Leverfunktionstests (ALT, AST, ALP, bilirubin)</li><li>Urea og elektrolytter / nyrepanel (kreatinin, eGFR, urea, kalium, natrium)</li><li>Lipider / kolesterolpanel (total kolesterol, triglycerider, HDL, LDL)</li><li>Prolaktin (PRL)</li><li>Testosteron og østradiol (T og E2)</li></ul><p>Hvis du er i gang med maskuliniserende hormonbehandling og tager dine opfølgende blodprøver, skal du som regel have taget disse blodprøver:</p><ul><li>Komplet blodtælling (FBC)</li><li>Leverfunktionstal (ALT, AST, ALP, bilirubin)</li><li>Lipider (totalkolesterol, triglycerider, HDL, LDL)</li><li>Testosteron og østradiol (T, E2)</li></ul><p>Hvis du er på <a href="https://min.medicin.dk/Medicin/Indholdsstoffer/318" target="_blank" rel="noreferrer">cyproteronacetat</a> (ofte Androcur), er det meget vigtigt, at du især holder øje med dine prolaktinniveauer. Cyproteronacetat har en lille chance for at give <a href="https://en.wikipedia.org/wiki/Prolactinoma" target="_blank" rel="noreferrer">prolaktinom</a>, hvilket er en godartet svulst i hypofysen. Det er ikke en almindelig bivirkning af cyproteronacetat, men hvis dine prolaktinniveauer er meget høje, er det vigtigt at tale med din læge.</p><p>Når du skal have taget blodprøver, kan du måske være forvirret over, hvor du skal have taget dem, da din egen læge højst sandsynligt ikke vil tage dem. Den bedste løsning i min oplevelse er at få taget blodprøverne ved <a href="https://ds-vt.dk/" target="_blank" rel="noreferrer">Dansk Sundhedsteam</a>. Man kan bestille blodprøver ved dem, hvorefter de så lægger dem ind på systemet så du kan bestille tid til blodprøvetagning ved et hospital i din region. Det er en super mulighed fordi du ikke behøver at tage ind på deres klinik men kan i stedet få taget dem på et hospital i nærheden af dig. Efter du har fået taget dem, bliver blodprøverne sendt til deres laboratorium. Når de har gjort deres arbejde, sender de dig resultaterne digitalt.</p><p>Det kan være lidt dyrt, men i min erfaring er det den billigste mulighed du har. Hvis du er i behandling ved Imago, kan du dog nævne det for dem, og de kan så trække moms fra prisen så du kan spare nogle penge.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};